app = FastAPI()
def read_value(item_id: int):
    return sum(range(1, item_id + 1))
@app.get("/items/{item_id}")
def read_item(value: int = Depends(read_value)):
    return {"value": value}
with TestClient(app) as client:
    print(client.get("/items/4").json()["value"])

